head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellChecked]<br/>Row 인덱스와 Column 정보를 사용하여 특정 Body Cell 의 체크 상태를 설정합니다.",
    "validation" : [
        "inputType 이 'checkbox','radio','custom' 인 경우에만 동작해야 합니다.",
        "rowIndex(필수) 파라미터로 체크 상태를 설정할 Body Cell 의 Row 인덱스를 설정해야 합니다. (Row 인덱스는 0 부터 시작하며 바인딩 된 DataList 기준으로 인덱스가 설정됩니다)",
        "columnInfo(필수) 파라미터로 체크 상태를 설정할 Body Cell 의 Column 인덱스를 설정해야 합니다.",
        "ckecked(필수) 파라미터가 true 면 해당 Body Cell 의 trueValue 속성값으로, false 면 falseValue 속성값으로 변환되어 DataList 에 저장되어야 합니다.",
        "ckecked 파라미터는 반드시 Boolean 타입이어야 하며, 숫자나 문자열 설정 시 메소드가 실행되지 않습니다.",        
        "inputType='custom' 이면 실제 Cell 의 inputType 이 'checkbox','radio' 인 Cell 만 처리해야 합니다.",
        "inputType='radio' 이고 ckecked 파라미터가 false 인 경우, 모든 Radio 가 선택 해제된 상태가 될 수 있습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 inputType 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="0:chk(checkbox·binary 1/0) / 1:name(text→미동작) / 2:rdo(radio·binary 1/0) / 3:cst(custom, Row0=checkbox·Row1=text·Row2=radio·Row3=checkbox) / 4:memo(text)"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    // - chk  : checkbox(binary) 원본값 1/0
    // - name : text 컬럼 (checkbox/radio 아님 → 미동작)
    // - rdo  : radio 원본값 1/0
    // - cst  : custom 컬럼 (행별 inputType 부여)
    // - memo : text 컬럼
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="rdo" name="rdo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cst" name="cst" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // Row0/Row2 = 체크(trueValue "1"), Row1/Row3 = 미체크(falseValue "0")
    // cst : Row0=checkbox(1=체크), Row1=text, Row2=radio(1=체크), Row3=checkbox(0=미체크)
    let jsonData = [
        { "chk": "1", "name": "John", "rdo": "1", "cst": "1",    "memo": "메모0" },
        { "chk": "0", "name": "Jane", "rdo": "0", "cst": "text", "memo": "메모1" },
        { "chk": "1", "name": "Mike", "rdo": "1", "cst": "1",    "memo": "메모2" },
        { "chk": "0", "name": "Amy",  "rdo": "0", "cst": "0",    "memo": "메모3" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    // setCellInputTypeCustom=true → custom 컬럼에 setCellInputType 으로 행별 inputType 부여 가능
    let properties = {
        dataList: "data:dlt_bind",
        setCellInputTypeCustom: "true",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 5컬럼)
    // 마지막 memo 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:660px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setCellChecked 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol1" value="chk(checkbox)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol2" value="name(text)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol3" value="rdo(radio)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol4" value="cst(custom)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol5" value="memo(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : chk (checkbox, valueType=binary) - trueValue="1" falseValue="0"
    strTarget += '<w2:column width="120" style="" inputType="checkbox" valueType="binary" id="chk" dataList="chk" trueValue="1" falseValue="0"></w2:column>';
    // index 1 : name (text) - checkbox/radio 아님 → 미동작
    strTarget += '<w2:column width="100" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 2 : rdo (radio, valueType=binary) - trueValue="1" falseValue="0"
    strTarget += '<w2:column width="100" style="" inputType="radio" valueType="binary" id="rdo" dataList="rdo" trueValue="1" falseValue="0"></w2:column>';
    // index 3 : cst (custom) - 행별 inputType 혼합 (setCellInputType 으로 지정)
    strTarget += '<w2:column width="110" style="" inputType="custom" id="cst" dataList="cst" trueValue="1" falseValue="0"></w2:column>';
    // index 4 : memo (text) - width="*"
    strTarget += '<w2:column width="*" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // cst(custom) 컬럼 행별 inputType 부여 (@spec1)
    //  Row0 = checkbox(1=체크), Row1 = text(체크 대상 아님), Row2 = radio(1=체크), Row3 = checkbox(0=미체크)
    target1.setCellInputType(0, "cst", { inputType: "checkbox" });
    target1.setCellInputType(1, "cst", { inputType: "text" });
    target1.setCellInputType(2, "cst", { inputType: "radio" });
    target1.setCellInputType(3, "cst", { inputType: "checkbox" });
}



// setCellChecked 실행 : par_rowIndex / par_columnInfo(컬럼 인덱스) / par_ckecked 로 호출
//  - ckecked='true'  → Boolean true  전달 → trueValue 저장
//  - ckecked='false' → Boolean false 전달 → falseValue 저장
//  - ckecked='num1'  → Number 1       전달 → Boolean 아님 → 미실행(값 불변)
//  - ckecked='str'   → 문자열 "true"  전달 → Boolean 아님 → 미실행(값 불변)
scwin.btn_setCellChecked_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let colIndex = Number(par_columnInfo.getValue());
    let cType = par_ckecked.getValue();

    // ckecked 파라미터 타입별 값 구성
    let ckecked;
    if (cType === 'true') {
        ckecked = true;          // Boolean true
    } else if (cType === 'false') {
        ckecked = false;         // Boolean false
    } else if (cType === 'num1') {
        ckecked = 1;             // Number (Boolean 아님 → 미실행)
    } else {
        ckecked = "true";        // String (Boolean 아님 → 미실행)
    }

    // 호출 전 DataList 저장값 (컬럼 ID 는 getCellInfo 로 조회)
    let colID = target1.getCellInfo(colIndex).id;
    let beforeData = dlt_bind.getCellData(rowIndex, colID);

    // setCellChecked 실행
    target1.setCellChecked(rowIndex, colIndex, ckecked);

    // 호출 후 DataList 저장값 / 체크 상태
    let afterData = dlt_bind.getCellData(rowIndex, colID);
    let checkedState = target1.getCellChecked(rowIndex, colIndex);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellChecked(" + rowIndex + ", " + colIndex + ", " + cType + ") → 저장값 " + beforeData + " -> " + afterData + " / getCellChecked=" + checkedState);
}
